window.HOEREN_TESTS[17] = {"id":"internet-und-technik","name":"Internet und Technik","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Achtung, liebe Mitarbeiter, eine wichtige Information vom IT-Team. Heute Abend ab 22 Uhr arbeiten wir am System. Bitte speichern Sie alle Dokumente vor 21 Uhr 30 — nach 22 Uhr funktioniert das Netzwerk nicht. Morgen früh ab 7 Uhr ist alles wieder normal. Bitte nicht früher anfangen! Vielen Dank für Ihre Mitarbeit!","gender":"m","q":"Was sollen Mitarbeiter machen?","opts":["Vor 21 Uhr 30 Dokumente speichern.","Vor 21 Uhr 30 nach Hause gehen.","Den ganzen Abend arbeiten."],"correct":0},{"transcript":"Hallo Sandra, hier ist Tom. Mein Handy ist kaputt — ich kann nichts mehr lesen, der Bildschirm ist schwarz. Ich gehe morgen zum Handy-Laden. Wenn du mich erreichen willst, ruf mich auf dem Festnetz an. Per Mail bin ich erst ab Donnerstag wieder, wenn das neue Handy da ist.","gender":"m","q":"Wie kann Sandra Tom erreichen?","opts":["Per Handy.","Per Mail sofort.","Per Festnetz."],"correct":2},{"transcript":"Liebe Kunden des Online-Shops Tech-Welt, wegen technischer Probleme funktioniert unser Webshop heute nicht. Über die Webseite können Sie also heute nicht bestellen. Sie können trotzdem im Geschäft einkaufen — wir haben heute besondere Angebote. Bestellungen über Telefon nehmen wir auch an: 089 / 555 666. Morgen ist die Webseite wieder online, nicht erst nächste Woche.","gender":"f","q":"Wie kann man heute bestellen?","opts":["Über die Webseite.","Erst morgen wieder.","Per Telefon oder im Geschäft."],"correct":2},{"transcript":"Hier ist Computer-Service Schnell. Ihr Laptop ist repariert: Die Festplatte war defekt, die haben wir gewechselt. Auch die Tastatur war kaputt — die haben wir auch ersetzt, nicht nur die Festplatte und nicht nur die Tastatur. Insgesamt kostet das 180 Euro. Sie können Ihr Gerät ab morgen zwischen 10 und 18 Uhr abholen. Bitte Ausweis mitbringen.","gender":"m","q":"Was wurde repariert?","opts":["Nur die Festplatte.","Festplatte und Tastatur.","Nur die Tastatur."],"correct":1},{"transcript":"Hallo Lukas, hier ist Mama. Also, das Internet zu Hause läuft nicht. Ich habe den Router schon ausgeschaltet und wieder eingeschaltet — hilft nicht. Kannst du vielleicht vorbeikommen und schauen, wenn du Zeit hast? Sonst muss ich den Techniker anrufen, das kostet Geld. Ruf bitte zurück, danke!","gender":"f","q":"Was möchte Mama von Lukas?","opts":["Den Router neu kaufen.","Vorbeikommen und schauen.","Mit dem Techniker telefonieren."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer bekommt was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Thomas","gender":"m","text":"Hallo Julia! Zu Weihnachten bekommt bei uns jeder ein Gerät. Ich habe die Wunschliste hier."},{"speaker":"Julia","gender":"f","text":"Dann gehen wir die Liste langsam durch. Unser Geld reicht dieses Jahr nicht für alles."},{"speaker":"Thomas","gender":"m","text":"Ich bekomme ein neues Smartphone. Mein altes Gerät geht am Abend oft aus."},{"speaker":"Julia","gender":"f","text":"Ein neues Smartphone brauchst du wirklich, Thomas. Wollten wir noch eine Kamera kaufen?"},{"speaker":"Thomas","gender":"m","text":"Nein. Eine Kamera kaufen wir nicht. Dafür fehlt uns das Geld."},{"speaker":"Julia","gender":"f","text":"Ich schaue abends gern Serien."},{"speaker":"Thomas","gender":"m","text":"Du bekommst ein Tablet, Julia. Du nimmst es abends mit in den Sessel."},{"speaker":"Julia","gender":"f","text":"Das Tablet ist leicht und praktisch. Lukas hört unterwegs gern Musik."},{"speaker":"Thomas","gender":"m","text":"Lukas bekommt kabellose Kopfhörer. Die alten Kabel stören ihn beim Laufen sehr."},{"speaker":"Julia","gender":"f","text":"Kopfhörer ohne Kabel finde ich sinnvoll. Sara läuft in der Früh auch viel."},{"speaker":"Thomas","gender":"m","text":"Sara bekommt eine Smartwatch. Sie will damit jeden Tag ihre Schritte zählen."},{"speaker":"Julia","gender":"f","text":"Eine Smartwatch passt gut zu ihr. Sollen wir ein Foto-Album aus Papier schenken?"},{"speaker":"Thomas","gender":"m","text":"Ein Foto-Album legen wir nicht unter den Baum. Die Bilder bleiben im Telefon."},{"speaker":"Julia","gender":"f","text":"Lisa schreibt lange Texte für die Schule."},{"speaker":"Thomas","gender":"m","text":"Lisa bekommt einen Laptop. Der alte Rechner ist für die Texte zu langsam."},{"speaker":"Julia","gender":"f","text":"Einverstanden. Ich bestelle alles noch heute Abend im Netz. Bis zum Fest."}],"options":[{"letter":"a","text":"kabellose Kopfhörer"},{"letter":"b","text":"eine Kamera"},{"letter":"c","text":"ein E-Reader"},{"letter":"d","text":"ein Tablet"},{"letter":"e","text":"eine Smartwatch"},{"letter":"f","text":"ein Foto-Album"},{"letter":"g","text":"ein neues Smartphone"},{"letter":"h","text":"ein Laptop"},{"letter":"i","text":"ein Spielcomputer"}],"items":[{"person":"Thomas","correct":"g"},{"person":"Julia","correct":"d"},{"person":"Lukas","correct":"a"},{"person":"Sara","correct":"e"},{"person":"Lisa","correct":"h"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Verkäufer","gender":"m","text":"Welches Modell suchen Sie?"},{"speaker":"Kundin","gender":"f","text":"Ein Smartphone, gutes Foto-Modul. Aber nicht zu teuer."},{"speaker":"Verkäufer","gender":"m","text":"Wir haben das X für 800 Euro, das Y für 500 Euro und das Z für 350 Euro."},{"speaker":"Kundin","gender":"f","text":"350 wäre besser, aber für Fotos ist das schlechter, oder?"},{"speaker":"Verkäufer","gender":"m","text":"Das Z ist okay, aber Y deutlich besser."},{"speaker":"Kundin","gender":"f","text":"Dann Y. Foto ist mir wichtig."}],"q":"Welches Modell kauft die Kundin?","opts":["X für 800 Euro.","Y für 500 Euro.","Z für 350 Euro."],"correct":1},{"lines":[{"speaker":"Mitarbeiter","gender":"m","text":"Guten Tag, was kann ich für Sie tun?"},{"speaker":"Kunde","gender":"m","text":"Mein Internet ist sehr langsam. Wir haben den Standard-Tarif. Den alten möchte ich nicht behalten."},{"speaker":"Mitarbeiter","gender":"m","text":"Wir können Sie auf den Premium-Tarif hochstufen, 30 Euro statt 20 Euro pro Monat."},{"speaker":"Kunde","gender":"m","text":"Was bringt das gegenüber Standard?"},{"speaker":"Mitarbeiter","gender":"m","text":"Dreimal schnelleres Internet, perfekt für Streaming. Standard bleibt langsam."},{"speaker":"Kunde","gender":"m","text":"Dann nehme ich Premium, nicht Standard und nicht den alten Tarif."}],"q":"Welcher Tarif jetzt?","opts":["Standard.","Er behält den alten.","Premium."],"correct":2},{"lines":[{"speaker":"Tochter","gender":"f","text":"Papa, kannst du mir helfen? Mein Computer geht nicht an. Ist er kaputt?"},{"speaker":"Vater","gender":"m","text":"Hast du den Akku-Stecker geprüft? Manchmal ist es nicht die Software, sondern der Stecker."},{"speaker":"Tochter","gender":"f","text":"Hmm, jetzt sehe ich — er ist nicht richtig drin. Der Computer selbst sieht okay aus."},{"speaker":"Vater","gender":"m","text":"Steck ihn richtig rein. Wahrscheinlich war das das Problem, kein Software-Problem."},{"speaker":"Tochter","gender":"f","text":"Es geht! Danke Papa. Also nicht kaputt, nur der Stecker."}],"q":"Was war das Problem?","opts":["Computer kaputt.","Stecker nicht richtig drin.","Software-Problem."],"correct":1},{"lines":[{"speaker":"Hotelgast","gender":"f","text":"Guten Tag, das WLAN funktioniert nicht in meinem Zimmer. Können Sie helfen?"},{"speaker":"Rezeption","gender":"f","text":"Gerne, welches Zimmer bitte? Ich prüfe das Passwort."},{"speaker":"Hotelgast","gender":"f","text":"Zimmer 207. Ich habe ‚Hotel2025‘ mit großen Buchstaben probiert, das ging nicht."},{"speaker":"Rezeption","gender":"f","text":"Ah, das Passwort hat sich geändert. Das neue ist ‚Hotel2025‘ — alles klein, nicht mit großen Buchstaben. 207 ist nur die Zimmernummer."},{"speaker":"Hotelgast","gender":"f","text":"Danke, ich probiere das gleich. Alles klein, verstanden."}],"q":"Was ist das neue Passwort?","opts":["Hotel2025 alles klein.","Hotel2025 mit großen Buchstaben.","Das Passwort ist 207."],"correct":0},{"lines":[{"speaker":"Sohn","gender":"m","text":"Mama, kann ich heute am Computer spielen? Nur eine Stunde, versprochen."},{"speaker":"Mutter","gender":"f","text":"Hast du deine Hausaufgaben gemacht? Englisch und der Rest? Schlafen gehen musst du noch nicht."},{"speaker":"Sohn","gender":"m","text":"Ja, die meisten. Nur Englisch fehlt noch."},{"speaker":"Mutter","gender":"f","text":"Englisch erst fertig machen, dann eine halbe Stunde Computer. Nicht sofort spielen."},{"speaker":"Sohn","gender":"m","text":"Okay, ich mache Englisch fertig und spiele danach. Danke Mama."}],"q":"Was macht der Sohn jetzt?","opts":["Sofort am Computer spielen.","Schlafen gehen.","Erst Englisch fertig machen."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Weber, einem IT-Berater. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Herr Weber, Sie sind IT-Berater seit 12 Jahren. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Weber","gender":"m","text":"Mein erster Computer war ein Geschenk meines Onkels. Ich war damals 10 Jahre alt. Ich habe stundenlang programmiert, statt zu spielen. Andere Kinder wollten Profi-Fußballer werden — ich wollte Software-Entwickler."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie genau als IT-Berater?"},{"speaker":"Weber","gender":"m","text":"Ich helfe Firmen, ihre Systeme zu verbessern. Manchmal entwickle ich Software, manchmal bilde ich Mitarbeiter aus, manchmal löse ich Probleme. Jeder Tag ist anders, das ist das Schöne."},{"speaker":"Reporter","gender":"m","text":"Arbeiten Sie im Büro?"},{"speaker":"Weber","gender":"m","text":"Selten. Etwa 70 Prozent meiner Arbeit mache ich im Homeoffice. In den anderen 30 Prozent der Zeit fahre ich zu Kunden, manchmal auch ins Ausland. Letztes Jahr war ich in Paris und in Mailand."},{"speaker":"Reporter","gender":"m","text":"Was ist das Schwierigste?"},{"speaker":"Weber","gender":"m","text":"Kunden zu erklären, warum Technik manchmal kompliziert ist. Sie wollen einfache Antworten, aber IT ist nicht immer einfach. Geduld brauchen wir beide."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie in der Freizeit?"},{"speaker":"Weber","gender":"m","text":"Ich nutze meinen Computer fast nicht privat. Stattdessen koche ich, gehe in die Natur, fotografiere. Das ist mein Ausgleich vom Bildschirm."}],"items":[{"q":"Er arbeitet meistens im Büro.","correct":"nein"},{"q":"Schon als Kind interessierte sich Herr Weber für Computer.","correct":"ja"},{"q":"Letztes Jahr war er auch im Ausland.","correct":"ja"},{"q":"Schwierige Kunden sind das Schwierigste an seinem Beruf.","correct":"nein"},{"q":"In seiner Freizeit nutzt er viel den Computer.","correct":"nein"}]}]};
